// Genera sub-ventanas mensuales half-open [monthStart, monthEnd) cubriendo [windowStart, windowEnd).
// Replica de month_windows() en python/src/ingestion/socrata.py (mantener ambas en sync).
// Regla skill chicago-data-ingestion: backfill por ventanas año/mes; nunca OFFSET profundo sin filtro de fechas.
const cfg = $input.first().json;
const start = cfg.windowStart;
const end = cfg.windowEnd;
if (start >= end) throw new Error(`windowStart (${start}) debe ser menor que windowEnd (${end})`);
const out = [];
let cursor = start;
while (cursor < end) {
  // año y mes del cursor (1-based desde el string ISO naive)
  const y = Number(cursor.slice(0, 4));
  const m = Number(cursor.slice(5, 7));
  // 1° del mes siguiente: Date.UTC(y, m, 1) con m 1-based cae en el mes siguiente
  // (los meses JS son 0-based) y diciembre rueda a enero del año siguiente.
  // UTC evita sorpresas de TZ: los timestamps de Socrata son naive y se tratan como texto.
  const nextIso = new Date(Date.UTC(y, m, 1)).toISOString().slice(0, 19);
  const monthEnd = nextIso < end ? nextIso : end;
  out.push({ json: { monthStart: cursor, monthEnd, datasetId: cfg.datasetId, pageSize: cfg.pageSize } });
  cursor = monthEnd;
}
return out;

// Validacion + serializacion del mes en curso. Dentro del bucle los conteos
// deben ser por iteracion: $input.all() esta acotado a esta ejecucion, mientras
// que $('Nodo').all() agregaria TODAS las iteraciones. Por eso la validacion
// vive aqui y no en un nodo Filter (reemplaza al Filter del Paso 2).
// Sin transformaciones de negocio: esas quedan en Postgres.
const items = $input.all().map(i => i.json);
const month = $('Loop Over Items').item.json; // item actual del bucle (via documentada)
const pageSize = Number(month.pageSize);
const received = items.length;
const valid = items.filter(r => r.id && r.date);
const failed = received - valid.length;
// Guard de truncamiento: si el mes devolvio pageSize registros puede haber
// quedado cortado. No insertamos nada (payload vacio) y queda FAILED para revision.
const truncated = received >= pageSize;
const payloadRecords = truncated ? [] : valid;
// El payload viaja como literal SQL: comillas + escape de apostrofes (' -> '').
const payloadSql = "'" + JSON.stringify(payloadRecords).replace(/'/g, "''") + "'";
const status = truncated ? 'FAILED' : (failed > 0 ? 'PARTIAL' : 'SUCCESS');
const errorMessage = (truncated
  ? `page_size ${pageSize} alcanzado en ${month.monthStart}: mes posiblemente truncado; requiere paginacion interna`
  : ''
).replace(/'/g, "''");
return [{ json: {
  payloadSql,
  received,
  valid: valid.length,
  failed,
  windowStart: month.monthStart,
  windowEnd: month.monthEnd,
  status,
  errorMessage,
  finishedAt: new Date().toISOString()
} }];
